mapper.select:


    and p.status = '0'
    and p.dept_id = #{deptId}
    and p.group_id = #{groupId}
    and p.student_id = #{studentId}
    and p.subject_id = #{subjectId}
    and p.practice_date = #{practiceDate}
    and p.finish_status = #{finishStatus}
    and p.proxy_flag = #{proxyFlag}
    and p.spot_status = #{spotStatus}
    and s.student_name like ('%' || #{studentName} || '%')
    and s.student_no like ('%' || #{studentNo} || '%')

        and p.practice_date >= cast(#{params.beginPracticeDate} as date)


        and p.practice_date <= cast(#{params.endPracticeDate} as date)



            and p.dept_id in
            #{did}

        ${params.dataScope}


order by p.practice_date desc, p.create_time desc

select book_name as "bookName", use_count as "useCount"
from spas_practice_book_stat
where dept_id = #{deptId} and subject_id = #{subjectId}
and book_name like ('%' || #{q} || '%')
order by use_count desc, last_used desc
limit #{limit}


where p.status = '0' and p.student_id = #{studentId}
  and p.practice_date between #{beginDate} and #{endDate}
order by p.practice_date desc, p.create_time desc

select p.student_id as "studentId", s.student_no as "studentNo", s.student_name as "studentName",
       count(distinct p.practice_date) as "proxyDays"
from spas_practice_log p
left join spas_student s on s.student_id = p.student_id
where p.status = '0' and p.proxy_flag = '1' and p.dept_id = #{deptId}
  and p.practice_date >= #{sinceDate}
  and p.subject_id = #{subjectId}
group by p.student_id, s.student_no, s.student_name
having count(distinct p.practice_date) >= #{minDays}
order by count(distinct p.practice_date) desc

select s.student_id as "studentId", s.student_no as "studentNo", s.student_name as "studentName",
       #{days} as "missingDays"
from spas_student s
where s.del_flag = '0' and s.status = '0' and s.dept_id = #{deptId}
  and (
    select count(1) from generate_series(
      (#{endDate}::date - (#{days} - 1)), #{endDate}::date, '1 day'::interval
    ) d(day)
    where not exists (
      select 1 from spas_practice_log p
      where p.student_id = s.student_id and p.practice_date = d.day::date and p.status = '0'
      and p.subject_id = #{subjectId}
    )
  ) >= #{days}
order by s.student_no

select
  (select count(1) from spas_student s where s.del_flag='0' and s.status='0' and s.dept_id=#{deptId}) as "studentTotal",
  (select count(distinct p.student_id) from spas_practice_log p
    where p.dept_id=#{deptId} and p.practice_date=#{practiceDate} and p.status='0'
    and p.subject_id=#{subjectId}
  ) as "submittedCount",
  (select count(1) from spas_practice_log p
    where p.dept_id=#{deptId} and p.practice_date=#{practiceDate} and p.status='0' and p.finish_status='3'
    and p.subject_id=#{subjectId}
  ) as "difficultyCount",
  (select count(1) from spas_practice_log p
    where p.dept_id=#{deptId} and p.practice_date=#{practiceDate} and p.status='0' and p.proxy_flag='1'
    and p.subject_id=#{subjectId}
  ) as "proxyCount"

select s.student_id as "studentId", s.student_no as "studentNo", s.student_name as "studentName",
       coalesce(prac.theme_count, 0) as "themeCount",
       coalesce(weak.weak_count, 0) as "weakCount",
       case when coalesce(weak.weak_count, 0) = 0 then null
            else round(coalesce(hit.hit_count, 0)::numeric / weak.weak_count, 4)
       end as "overlapRate"
from spas_student s
left join (
    select p.student_id, count(distinct pk.knowledge_id) as theme_count
    from spas_practice_log p
    join spas_practice_log_knowledge pk on pk.log_id = p.log_id
    where p.dept_id = #{deptId} and p.status = '0'
      and p.practice_date between #{beginDate} and #{endDate}
      and p.subject_id = #{subjectId}
    group by p.student_id
) prac on prac.student_id = s.student_id
left join (
    select st.student_id, count(1) as weak_count
    from (
        select sk.student_id, sk.knowledge_id,
               row_number() over (partition by sk.student_id order by sk.weighted_rate asc nulls last) as rn
        from spas_student_knowledge_stat sk
        join spas_knowledge k on k.knowledge_id = sk.knowledge_id
        where sk.student_id in (select student_id from spas_student where dept_id = #{deptId} and del_flag='0')
          and k.subject_id = #{subjectId}
    ) st where st.rn <= 5
    group by st.student_id
) weak on weak.student_id = s.student_id
left join (
    select p.student_id, count(distinct pk.knowledge_id) as hit_count
    from spas_practice_log p
    join spas_practice_log_knowledge pk on pk.log_id = p.log_id
    where p.dept_id = #{deptId} and p.status = '0'
      and p.practice_date between #{beginDate} and #{endDate}
      and p.subject_id = #{subjectId}
      and pk.knowledge_id in (
        select sk.knowledge_id from (
          select sk2.student_id, sk2.knowledge_id,
                 row_number() over (partition by sk2.student_id order by sk2.weighted_rate asc nulls last) rn
          from spas_student_knowledge_stat sk2
          join spas_knowledge k2 on k2.knowledge_id = sk2.knowledge_id
          where 1=1
          and k2.subject_id = #{subjectId}
        ) sk where sk.rn <= 5 and sk.student_id = p.student_id
      )
    group by p.student_id
) hit on hit.student_id = s.student_id
where s.del_flag = '0' and s.status = '0' and s.dept_id = #{deptId}
order by case when coalesce(weak.weak_count, 0) = 0 then null
              else round(coalesce(hit.hit_count, 0)::numeric / weak.weak_count, 4)
         end nulls first, s.student_no

select p.log_id as "logId", p.student_id as "studentId", s.student_no as "studentNo",
       s.student_name as "studentName", p.book_name as "bookName",
       p.page_from as "pageFrom", p.page_to as "pageTo", p.question_text as "questionText",
       p.practice_date as "practiceDate", p.spot_status as "spotStatus"
from spas_practice_log p
left join spas_student s on s.student_id = p.student_id
where p.status = '0' and p.dept_id = #{deptId}
  and p.practice_date between #{beginDate} and #{endDate}
  and coalesce(p.spot_status, '0') = '0'
  and p.subject_id = #{subjectId}
order by random()
limit #{limit}

select d.device_id as "deviceId", d.device_code as "deviceCode", d.device_name as "deviceName", d.dept_id as "deptId", dept.dept_name as "deptName", d.status as "status", d.last_seen as "lastSeen", d.last_student_id as "lastStudentId", s.student_name as "lastStudentName", d.app_version as "appVersion" from spas_kiosk_device d left join sys_dept dept on dept.dept_id = d.dept_id left join spas_student s on s.student_id = d.last_student_id
and d.dept_id = #{deptId}
order by d.last_seen desc nulls last


where p.status = '0' and p.proxy_flag = '1' and p.confirm_status = '1'
  and p.student_id = #{studentId}
order by p.practice_date desc, p.create_time desc
